<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\GdprConsent\Infrastructure\Driver\Rest;

use DateTime;
use Throwable;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\GdprConsentListItem;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\Gateway\GdprConsentGateway;

final class MeConsentsListController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly Context $context,
        private readonly GdprConsentGateway $gateway,
    ) {
    }

    #[OA\Get(
        path: '/api/me/consents',
        summary: 'List GDPR consent purposes with user decision status',
        tags: ['Me - GDPR Consents'],
        security: [['bearerAuth' => []]],
        responses: [
            new OA\Response(
                response: 200,
                description: 'OK',
                content: new OA\JsonContent(type: 'array', items: new OA\Items(ref: '#/components/schemas/MeConsentApiDTO'))
            ),
            new OA\Response(response: 401, description: 'Unauthorized'),
        ]
    )]
    public function list(ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        $this->logDebug('List me/consents');
        $span = $this->startSpan('List me/consents');
        try {
            $identity = $this->context->getIdentity();
            if ($identity->anonymous || null === $identity->id) {
                throw new UnauthorizedException();
            }

            $items = $this->gateway->listConsents($identity->id, $identity->tenant ?? '');
            $dtos = array_map([$this, 'mapItem'], $items);

            $encoded = json_encode($dtos);
            $response->getBody()->write($encoded !== false ? $encoded : '[]');
            return $response->withStatus(200)->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapItem(GdprConsentListItem $item): MeConsentApiDTO
    {
        $dto = new MeConsentApiDTO();
        $dto->purposeUid = $item->purposeUid;
        $dto->purposeKey = $item->purposeKey;
        $dto->title = $item->title;
        $dto->description = $item->description;
        $dto->required = $item->required;
        $dto->granted = $item->granted;
        $dto->decisionAt = $item->decisionAt?->format(DateTime::ATOM);
        return $dto;
    }
}
